/**
 * Protect Line design tokens
 * Source of truth for Claude Design, Cursor, and all HTML specimens.
 * Do not invent colours outside this file.
 */

@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@1,700&family=Poppins:ital,wght@0,400;0,600;0,700;1,400&display=swap');

:root {
  /* ── Brand primaries ── */
  --color-navy: #0c073d;
  --color-white: #ffffff;
  --color-hot-pink: #f20779;

  /* ── Secondary blues (backgrounds / sections only) ── */
  --color-mid-blue: #a3c8f5;
  --color-light-blue: #cfdbf2;
  --color-fair-blue: #ecf1fa;

  /* ── Secondary pinks ── */
  --color-mid-pink: #ff61b1;
  --color-light-pink: #fdb3df;
  --color-fair-pink: #fce6f2;

  /* ── Figma Dark Blue ramp (optional primitives) ── */
  --color-dark-blue-50: #f4f3f9;
  --color-dark-blue-100: #e8e7f3;
  --color-dark-blue-200: #c5c3e0;
  --color-dark-blue-300: #9f9ccb;
  --color-dark-blue-400: #6b67a8;
  --color-dark-blue-500: #3a337d;
  --color-dark-blue-600: #2a2368;
  --color-dark-blue-700: #18124d;
  --color-dark-blue-800: #0c073d;
  --color-dark-blue-900: #08052e;

  /* ── Figma Pink ramp (optional primitives) ── */
  --color-pink-50: #fce6f2;
  --color-pink-100: #fdb3df;
  --color-pink-200: #fdb3df;
  --color-pink-300: #ff61b1;
  --color-pink-400: #ff4da6;
  --color-pink-500: #f20779;
  --color-pink-600: #d9066c;
  --color-pink-700: #b8055a;
  --color-pink-800: #97044a;
  --color-pink-900: #76033a;

  /* ── Semantic colours ── */
  --color-bg-primary: var(--color-navy);
  --color-bg-secondary: var(--color-fair-blue);
  --color-bg-surface: var(--color-white);
  --color-bg-nav: var(--color-dark-blue-700);
  --color-bg-nav-border: var(--color-dark-blue-500);
  --color-text-primary: var(--color-navy);
  --color-text-on-dark: var(--color-white);
  --color-text-on-navy-heading: var(--color-light-pink);
  --color-text-link: var(--color-hot-pink);
  --color-cta-bg: var(--color-hot-pink);
  --color-cta-border: var(--color-mid-pink);
  --color-cta-text: var(--color-white);
  --color-graph: var(--color-mid-pink);
  --color-icon-bg: var(--color-fair-pink);

  /* ── Typography ── */
  --font-primary: 'Poppins', Arial, sans-serif;
  --font-accent: 'Lora', Georgia, serif;
  --font-fallback: Arial, sans-serif;

  --font-size-display: 3rem;
  --font-size-h1: 2.5rem;
  --font-size-h2: 2rem;
  --font-size-h3: 1.5rem;
  --font-size-h4: 1.25rem;
  --font-size-body: 1rem;
  --font-size-small: 0.875rem;
  --font-size-caption: 0.75rem;
  --font-size-button: 1rem;

  --font-weight-regular: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  --line-height-tight: 1.2;
  --line-height-body: 1.6;
  --line-height-heading: 1.3;

  --letter-spacing-tight: -0.01em;
  --letter-spacing-normal: 0;
  --letter-spacing-wide: 0.08em;
  --letter-spacing-tracked: 0.15em;

  /* ── Spacing (Design System Foundations naming) ── */
  --spacing-xxsm: 4px;
  --spacing-xsm: 8px;
  --spacing-sm: 12px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xlg: 32px;
  --spacing-hg: 40px;
  --spacing-xhg: 48px;
  --spacing-xxlg: 64px;
  --spacing-xxhg: 80px;
  --spacing-xxxhg: 96px;
  --spacing-enorm: 128px;

  /* ── Layout ── */
  --container-max: 1200px;
  --container-padding: var(--spacing-lg);
  --section-padding-y: var(--spacing-xxhg);
  --grid-gap: var(--spacing-lg);

  /* ── Radius ── */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 100px;
  --radius-card: var(--radius-lg);

  /* ── Depth (minimal — brand is mostly flat) ── */
  --shadow-nav: 0 2px 6px rgba(16, 24, 40, 0.06);
  --shadow-none: none;

  /* ── Motion ── */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
}

/* ── Base reset ── */
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-primary);
  font-size: var(--font-size-body);
  line-height: var(--line-height-body);
  color: var(--color-text-primary);
  background: var(--color-bg-surface);
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-text-link);
  font-weight: var(--font-weight-bold);
  text-decoration: underline;
}

/* ── Type scale utilities ── */
.pl-display {
  font-family: var(--font-primary);
  font-size: var(--font-size-display);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
}

.pl-h1 {
  font-family: var(--font-primary);
  font-size: var(--font-size-h1);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-heading);
}

.pl-h2 {
  font-family: var(--font-primary);
  font-size: var(--font-size-h2);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-heading);
}

.pl-h3 {
  font-family: var(--font-primary);
  font-size: var(--font-size-h3);
  font-weight: var(--font-weight-semibold);
  line-height: var(--line-height-heading);
}

.pl-subheading-caps {
  font-family: var(--font-primary);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-regular);
  letter-spacing: var(--letter-spacing-tracked);
  text-transform: uppercase;
}

.pl-section-heading {
  font-family: var(--font-primary);
  font-size: var(--font-size-h3);
  font-weight: var(--font-weight-bold);
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-wide);
  background: var(--color-navy);
  color: var(--color-white);
  padding: var(--spacing-sm) var(--spacing-lg);
  display: inline-block;
}

.pl-body {
  font-family: var(--font-primary);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-regular);
  line-height: var(--line-height-body);
}

.pl-quote {
  font-family: var(--font-accent);
  font-size: var(--font-size-h3);
  font-weight: var(--font-weight-bold);
  font-style: italic;
  line-height: var(--line-height-heading);
  text-align: center;
}

.pl-mixed-heading .pl-mixed-sans {
  font-family: var(--font-primary);
  font-weight: var(--font-weight-bold);
}

.pl-mixed-heading .pl-mixed-serif {
  font-family: var(--font-accent);
  font-weight: var(--font-weight-bold);
  font-style: italic;
}

.pl-highlighter {
  background: var(--color-hot-pink);
  color: var(--color-white);
  padding: 0 var(--spacing-xsm);
}

.pl-underline-accent {
  position: relative;
  display: inline-block;
}

.pl-underline-accent::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 4px;
  background: var(--color-hot-pink);
  border-radius: 2px;
  transform: rotate(-1deg);
}

/**
 * Protect Line component styles
 * All values reference tokens from colors_and_type.css
 */

/* ── Buttons ── */
.pl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-xsm);
  font-family: var(--font-primary);
  font-size: var(--font-size-button);
  font-weight: var(--font-weight-bold);
  line-height: 1.5;
  text-decoration: none;
  border: 2px solid transparent;
  border-radius: var(--radius-pill);
  padding: var(--spacing-sm) var(--spacing-hg);
  cursor: pointer;
  transition: background var(--transition-fast), border-color var(--transition-fast), opacity var(--transition-fast);
  min-height: 44px;
  white-space: nowrap;
}

.pl-btn-primary {
  background: var(--color-cta-bg);
  border-color: var(--color-cta-border);
  color: var(--color-cta-text);
  position: relative;
  overflow: hidden;
}

.pl-btn-primary:hover {
  background: var(--color-pink-600);
}

.pl-btn-primary:focus-visible {
  outline: 2px solid var(--color-white);
  outline-offset: 2px;
}

.pl-btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.pl-btn-secondary {
  background: transparent;
  border-color: var(--color-navy);
  color: var(--color-navy);
}

.pl-btn-secondary:hover {
  background: var(--color-fair-blue);
}

.pl-btn-secondary-light {
  background: transparent;
  border-color: var(--color-white);
  color: var(--color-white);
}

.pl-btn-secondary-light:hover {
  background: rgba(255, 255, 255, 0.1);
}

.pl-btn-tertiary {
  background: none;
  border: none;
  border-radius: 0;
  padding: 0;
  color: var(--color-hot-pink);
  text-decoration: underline;
  min-height: auto;
}

.pl-link {
  color: var(--color-text-link);
  font-weight: var(--font-weight-bold);
  text-decoration: underline;
}

.pl-link:hover {
  color: var(--color-pink-600);
}

/* ── Header / Navigation ── */
.pl-header {
  background: var(--color-bg-nav);
  border: 1px solid var(--color-bg-nav-border);
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-nav);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-xsm) var(--spacing-xsm) var(--spacing-xsm) var(--spacing-sm);
  max-width: var(--container-max);
  margin: 0 auto;
  gap: var(--spacing-lg);
}

.pl-header__logo {
  height: 43px;
  width: auto;
  flex-shrink: 0;
}

.pl-header__logo img {
  height: 100%;
  width: auto;
}

.pl-header__nav {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
  list-style: none;
  margin: 0;
  padding: 0;
}

.pl-header__nav a {
  color: var(--color-text-on-dark);
  font-weight: var(--font-weight-bold);
  font-size: var(--font-size-body);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: var(--spacing-xxsm);
}

.pl-header__nav a:hover {
  color: var(--color-light-pink);
}

.pl-header__menu-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--color-white);
  font-size: 1.5rem;
  cursor: pointer;
  padding: var(--spacing-xsm);
  min-width: 44px;
  min-height: 44px;
}

/* ── Hero ── */
.pl-hero {
  padding: var(--spacing-xxhg) var(--container-padding);
  text-align: center;
}

.pl-hero--navy {
  background: var(--color-navy);
  color: var(--color-text-on-dark);
}

.pl-hero--fair-blue {
  background: var(--color-fair-blue);
  color: var(--color-text-primary);
}

.pl-hero__eyebrow {
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-regular);
  letter-spacing: var(--letter-spacing-tracked);
  text-transform: uppercase;
  margin-bottom: var(--spacing-md);
}

.pl-hero__title {
  font-size: var(--font-size-display);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
  margin: 0 0 var(--spacing-lg);
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}

.pl-hero__subtitle {
  font-size: var(--font-size-h4);
  font-weight: var(--font-weight-regular);
  line-height: var(--line-height-body);
  margin: 0 0 var(--spacing-xhg);
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

.pl-hero__actions {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* ── Cards ── */
.pl-card {
  border-radius: var(--radius-card);
  overflow: hidden;
}

.pl-card-product {
  background: var(--color-white);
  border: 1px solid var(--color-light-blue);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.pl-card-product__title {
  font-size: var(--font-size-h3);
  font-weight: var(--font-weight-bold);
  margin: 0;
}

.pl-card-product__text {
  font-size: var(--font-size-body);
  margin: 0;
  flex: 1;
}

.pl-card-expandable {
  border: 1px solid var(--color-light-blue);
  border-radius: var(--radius-card);
  overflow: hidden;
}

.pl-card-expandable__header {
  background: var(--color-navy);
  color: var(--color-white);
  padding: var(--spacing-md) var(--spacing-lg);
  font-weight: var(--font-weight-bold);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 44px;
}

.pl-card-expandable__body {
  background: var(--color-fair-blue);
  padding: var(--spacing-md) var(--spacing-lg);
  display: none;
}

.pl-card-expandable.is-open .pl-card-expandable__body {
  display: block;
}

.pl-card-review {
  background: var(--color-white);
  border: 1px solid var(--color-light-blue);
  border-radius: var(--radius-card);
  padding: var(--spacing-lg);
}

.pl-card-review__stars {
  color: var(--color-hot-pink);
  font-size: var(--font-size-h4);
  margin-bottom: var(--spacing-sm);
}

.pl-card-review__quote {
  font-size: var(--font-size-body);
  line-height: var(--line-height-body);
  margin: 0 0 var(--spacing-md);
}

.pl-card-review__author {
  font-weight: var(--font-weight-bold);
  font-size: var(--font-size-small);
}

.pl-card-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xhg);
  align-items: center;
}

.pl-card-content__image {
  border-radius: var(--radius-card);
  background: var(--color-fair-blue);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-dark-blue-400);
  font-size: var(--font-size-small);
}

/* ── Footer ── */
.pl-footer {
  background: var(--color-navy);
  color: var(--color-text-on-dark);
  padding: var(--spacing-xxhg) var(--container-padding) var(--spacing-lg);
}

.pl-footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--spacing-xhg);
  max-width: var(--container-max);
  margin: 0 auto var(--spacing-xhg);
}

.pl-footer__column h4 {
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-bold);
  margin: 0 0 var(--spacing-md);
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-wide);
}

.pl-footer__column ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.pl-footer__column a {
  color: var(--color-text-on-dark);
  text-decoration: none;
  font-weight: var(--font-weight-regular);
  font-size: var(--font-size-small);
  line-height: 2;
}

.pl-footer__column a:hover {
  color: var(--color-light-pink);
}

.pl-footer__bottom {
  border-top: 1px solid var(--color-dark-blue-500);
  padding-top: var(--spacing-lg);
  max-width: var(--container-max);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--font-size-caption);
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

/* ── FAQ Accordion ── */
.pl-accordion {
  max-width: var(--container-max);
  margin: 0 auto;
}

.pl-accordion__item {
  border-bottom: 1px solid var(--color-light-blue);
}

.pl-accordion__question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: var(--spacing-md) 0;
  font-family: var(--font-primary);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-bold);
  color: var(--color-navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 44px;
}

.pl-accordion__answer {
  padding: 0 0 var(--spacing-md);
  font-size: var(--font-size-body);
  line-height: var(--line-height-body);
  display: none;
}

.pl-accordion__item.is-open .pl-accordion__answer {
  display: block;
}

/* ── Tags ── */
.pl-tag {
  display: inline-block;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  padding: var(--spacing-xxsm) var(--spacing-sm);
  border-radius: var(--radius-pill);
  background: var(--color-fair-pink);
  color: var(--color-navy);
}

.pl-tag--outline {
  background: transparent;
  border: 1px solid var(--color-navy);
}

/* ── Testimonial ── */
.pl-testimonial {
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
  padding: var(--spacing-xhg);
}

.pl-testimonial__quote {
  font-family: var(--font-accent);
  font-size: var(--font-size-h3);
  font-weight: var(--font-weight-bold);
  font-style: italic;
  line-height: var(--line-height-heading);
  margin: 0 0 var(--spacing-lg);
}

.pl-testimonial__author {
  font-weight: var(--font-weight-bold);
  font-size: var(--font-size-body);
}

.pl-testimonial__role {
  font-size: var(--font-size-small);
  color: var(--color-dark-blue-400);
}

/* ── Section layout helpers ── */
.pl-section {
  padding: var(--section-padding-y) var(--container-padding);
}

.pl-section--fair-blue {
  background: var(--color-fair-blue);
}

.pl-section--navy {
  background: var(--color-navy);
  color: var(--color-text-on-dark);
}

.pl-container {
  max-width: var(--container-max);
  margin: 0 auto;
}

.pl-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--grid-gap);
}

/* ── Responsive ── */
@media (max-width: 767px) {
  .pl-header__nav,
  .pl-header__cta {
    display: none;
  }

  .pl-header__menu-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .pl-header.is-open .pl-header__nav {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--color-bg-nav);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    margin-top: var(--spacing-xsm);
    z-index: 100;
  }

  .pl-header {
    position: relative;
    flex-wrap: wrap;
  }

  .pl-hero__title {
    font-size: var(--font-size-h1);
  }

  .pl-card-content {
    grid-template-columns: 1fr;
  }

  .pl-footer__grid {
    grid-template-columns: 1fr 1fr;
  }

  .pl-grid-3 {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 479px) {
  .pl-footer__grid {
    grid-template-columns: 1fr;
  }
}
